-- =====================================================================
-- 02_business_performance.sql
-- Block 1 · Overall performance: what is happening in the business?
-- Revenue = completed orders only
-- =====================================================================

-- Q: What is the total revenue generated by the company?
-- Result: 172,985 €
SELECT SUM(total_amount) AS total_revenue
FROM transactions
WHERE order_status = 'completed';


-- Q: What is the average ticket per transaction?
-- Result: 302.95 € (578 completed transactions)
SELECT
    COUNT(*)                     AS total_transactions,
    ROUND(AVG(total_amount), 2)  AS avg_ticket
FROM transactions
WHERE order_status = 'completed';


-- Q: How do sales evolve over time?
-- Result: lowest months are June (8,820 €), September (10,420 €) and July (11,070 €);
--         monthly average ≈ 14,400 €. No clear seasonality with a single year of data.
-- Note: the output also shows 2024-01 (120 €, outlier) and a NULL month (690 €, transactions without date)
SELECT
    DATE_TRUNC('month', date) AS month,
    SUM(total_amount)         AS total_sales
FROM transactions
WHERE order_status = 'completed'
GROUP BY month
ORDER BY month;
